$biology_content$::jsonb;
begin
  select subject.id into strict subject_id_value
  from public.study_subjects as subject
  join public.study_semesters as semester on semester.id = subject.semester_id
  join public.institutions as institution on institution.id = semester.institution_id
  where institution.slug = 'fizjoluj-pilot' and semester.semester_number = 1 and subject.name = 'Biologia medyczna';

  for chapter in select value from jsonb_array_elements(syllabus) loop
    chapter_position := chapter_position + 1;
    insert into public.study_sections (subject_id, name, position)
      values (subject_id_value, chapter->>'name', chapter_position)
      on conflict (subject_id, name) do nothing;
    select id into strict section_id_value from public.study_sections
      where subject_id = subject_id_value and name = chapter->>'name';

    topic_position := 0;
    for lesson in select value from jsonb_array_elements(chapter->'topics') loop
      topic_position := topic_position + 1;
      insert into public.study_topics (section_id, name, position)
        values (section_id_value, lesson->>'title', topic_position)
        on conflict (section_id, name) do nothing;
      select id into strict topic_id_value from public.study_topics
        where section_id = section_id_value and name = lesson->>'title';

      insert into public.study_topic_revisions
        (topic_id, revision_number, notes, mnemonic, correction, source_label, source_url, flashcards)
      values (topic_id_value, 1, array(select jsonb_array_elements_text(lesson->'notes')),
        lesson->>'mnemonic', lesson->>'correction', lesson->>'sourceLabel', lesson->>'sourceUrl',
        jsonb_build_array(jsonb_build_object(
          'id', md5('fizjoluj:biologia:flashcard:' || (lesson->>'number'))::uuid,
          'prompt', lesson->>'title', 'answer', lesson->>'answer'
        )))
      on conflict (topic_id, revision_number) do nothing
      returning id into draft_id;

      if found then
        insert into public.study_topic_revision_quizzes (revision_id, items)
        values (draft_id, jsonb_build_array(jsonb_build_object(
          'id', md5('fizjoluj:biologia:quiz:' || (lesson->>'number'))::uuid,
          'prompt', lesson->>'question', 'options', lesson->'options',
          'correctOption', 0, 'explanation', lesson->>'mnemonic'
        )));
      end if;
    end loop;
  end loop;
end;
$biology_seed$;

commit;
